def _migration_batches(self, query: str) -> None:
    authorized, record = self._authorize()
    if not authorized:
        return

    try:
        params = _parse_migration_batches_params(query)
    except ValueError:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return

    # Scope checks follow parameter validation and precede any access
    # to the coordination ledger. An exact batch lookup needs
    # unrestricted operation and stage scopes and a key scope that is
    # unrestricted or names the requested batch; a paginated query
    # needs all three scopes unrestricted. A forbidden request never
    # opens the ledger or any business file.
    if record is not None:
        if record.ops is not None or record.stages is not None:
            self._json(HTTPStatus.FORBIDDEN, {"error": "forbidden"})
            return
        if "key" in params:
            if record.keys is not None \
                    and params["key"] not in record.keys:
                self._json(HTTPStatus.FORBIDDEN,
                           {"error": "forbidden"})
                return
        elif record.keys is not None:
            self._json(HTTPStatus.FORBIDDEN, {"error": "forbidden"})
            return

    ledger_path = getattr(self.server, "migration_batches_path")
    try:
        if "key" in params:
            body = migration_batch.get_response(
                ledger_path, params["key"])
        else:
            kwargs: dict[str, object] = {}
            if "cursor" in params:
                kwargs["cursor"] = params["cursor"]
            if "limit" in params:
                kwargs["limit"] = int(params["limit"])
            body = migration_batch.search_response(
                ledger_path, **kwargs)
    except FileNotFoundError:
        # The one coordination ledger fixed at startup is absent; the
        # configured path and system messages never leak.
        self._json(HTTPStatus.NOT_FOUND,
                   {"error": "migration_batches_not_found"})
    except KeyError:
        self._json(HTTPStatus.NOT_FOUND,
                   {"error": "migration_batch_not_found"})
    except ValueError:
        # Non-canonical coordination bytes, a broken reference or a
        # missing referenced business ledger.
        self._json(HTTPStatus.CONFLICT,
                   {"error": "migration_batches_invalid"})
    except OSError:
        self._json(HTTPStatus.SERVICE_UNAVAILABLE,
                   {"error": "migration_batches_unavailable"})
    else:
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

def _raw(self, status: HTTPStatus, body: bytes, etag: str) -> None:
